<?php $title='Manage products';require '../includes/header.php';if(!is_admin())redirect('../auth/login.php');if($_SERVER['REQUEST_METHOD']==='POST'){if($_POST['action']==='delete'){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['id']]);flash('Product deleted.');}else{$s=$pdo->prepare('INSERT INTO products(name,category,description,price,old_price,image,stock,rating,badge) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$_POST['name'],$_POST['category'],$_POST['description'],$_POST['price'],$_POST['old_price']?:null,$_POST['image'],$_POST['stock'],$_POST['rating'],$_POST['badge']]);flash('Product added.');}redirect('products.php');}$items=$pdo->query('SELECT * FROM products ORDER BY id DESC')->fetchAll(); ?><section class="container section"><span class="eyebrow">ADMIN • CATALOG</span><h1>Product management</h1><div class="adminForm"><form method="post"><input type="hidden" name="action" value="add"><input name="name" placeholder="Product name" required><select name="category"><option>Electronics</option><option>Wearables</option><option>Fashion</option><option>Home</option></select><input name="price" type="number" placeholder="Price" required><input name="old_price" type="number" placeholder="Old price"><input name="stock" type="number" placeholder="Stock" required><input name="rating" step="0.1" value="4.5" placeholder="Rating"><input name="badge" value="New" placeholder="Badge"><input name="image" value="phone.svg" placeholder="Image filename"><textarea name="description" placeholder="Description"></textarea><button class="btn primary">Add product</button></form></div><div class="tableWrap"><table><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr><?php foreach($items as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td>₹<?=number_format($p['price'])?></td><td><?=$p['stock']?></td><td><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="dangerBtn">Delete</button></form></td></tr><?php endforeach;?></table></div></section><?php require '../includes/footer.php'; ?>